import {readGenerationTarget} from "@/lib/agent/generationRuntime";
import {db} from "./database";
import {editableAgentTask} from "./agentTasks";
import type {AgentTaskRecord, TaskRecordInput, TaskRecordSource} from "@/domain/agentTaskRecords";
import {TASK_RECORD_CLAIMS, TASK_RECORD_KINDS} from "@/domain/agentTaskRecords";
import type {AgentTask, AgentToolCall} from "@/domain/agent";
import {createId, nowIso} from "@/lib/ids";
import {
    ownedTaskAudioGenerationJob,
    SOUND_GENERATION_TOOLS,
    taskAudioGenerationSource,
    taskAudioToolSource
} from "./taskAudioGenerationEvidence";

export async function listTaskRecords(taskId: string): Promise<AgentTaskRecord[]> {
    return db.agentTaskRecords.where("taskId").equals(taskId).sortBy("updatedAt");
}

export async function listTaskRecordVersions(taskId: string, recordId: string) {
    const record = await db.agentTaskRecords.get(recordId);
    if (!record || record.taskId !== taskId) throw new Error("记录不属于当前任务");
    return db.agentTaskRecordVersions.where("recordId").equals(recordId).sortBy("revision");
}

/** A completed ledger entry may describe a failed remote job or an apply conflict. */
export function provesCompletedEffect(call: AgentToolCall): boolean {
    let value: unknown;
    try {
        value = JSON.parse(call.result ?? "null");
    } catch {
        return false;
    }
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    const result = value as Record<string, unknown>;
    if (result.error || result.ok === false || result.success === false) return false;
    if (["submit_generation", "check_generation", "apply_generation"].includes(call.name)) {
        const media = result.result as { mediaId?: unknown; kind?: unknown } | undefined;
        return (call.name === "apply_generation" ? result.status === "applied" && result.applied === true : result.status === "downloaded" || result.status === "applied") &&
            typeof media?.mediaId === "string" && !!media.mediaId && (media.kind === "image" || media.kind === "video");
    }
    // Other network tools can report a check without producing a business result.
    return call.effect === "write" && result.applied !== false;
}

export async function validateTaskSources(task: Pick<AgentTask, "id" | "threadId">, sources: TaskRecordSource[], claim: TaskRecordInput["claim"], author: "ai" | "user") {
    if (!Array.isArray(sources) || sources.length > 12) throw new Error("来源最多 12 项");
    let userEvidence = false, completedEffect = false;
    for (const source of sources) {
        if (!source.id || source.id.length > 120) throw new Error("来源标识无效");
        if (source.type === "message") {
            const message = await db.chatMessages.get(source.id);
            if (!message || message.threadId !== task.threadId || message.role !== "user" || (!message.content.trim() && !message.attachments?.length)) throw new Error("只能引用当前对话真实的用户消息");
            userEvidence = true;
        } else if (source.type === "tool") {
            const call = await db.agentToolCalls.get(source.id);
            const run = call && await db.agentRuns.get(call.runId);
            if (!call || !run || call.threadId !== task.threadId || run.threadId !== task.threadId || run.taskId !== task.id || call.status !== "completed" || !call.result || call.effect === "bookkeeping") throw new Error("来源不是当前任务已完成的业务工具结果");
            if ((SOUND_GENERATION_TOOLS as readonly string[]).includes(call.name)) {
                const evidence = await taskAudioToolSource(task, call);
                completedEffect ||= evidence?.supportsResult === true;
            } else completedEffect ||= provesCompletedEffect(call);
        } else if (source.type === "generation") {
            const evidence = await taskGenerationSource(task, source.id);
            completedEffect ||= evidence.supportsResult;
        } else throw new Error("来源类型无效");
    }
    if (author === "ai" && claim === "decision" && !userEvidence) throw new Error("确认决策必须引用用户消息");
    if (author === "ai" && claim === "result" && !completedEffect) throw new Error("完成结果必须引用已完成的实际业务操作");
    if (author === "ai" && claim === "observation" && sources.length === 0) throw new Error("调研观察必须附真实来源；未核实内容请记为方案或待解决问题");
}

/** Transaction-internal write, shared by guarded manual saves and ledger-atomic tools. */
export async function writeTaskRecord(task: AgentTask, input: TaskRecordInput, options: {
    id?: string;
    expectedRevision?: number;
    author: "user" | "ai";
    runId?: string;
    requirementSnapshot?: boolean
}): Promise<AgentTaskRecord> {
    if (task.lifecycle !== "open") throw new Error("请先重新打开任务");
    if (!TASK_RECORD_KINDS.includes(input.kind) || !TASK_RECORD_CLAIMS.includes(input.claim) || !input.title.trim() || input.title.length > 120 || !input.body.trim() || input.body.length > (options.requirementSnapshot ? 100_000 : 12_000)) throw new Error("记录类型或内容无效：标题最多 120 字，正文最多 12,000 字");
    if (input.todoId && !task.plan.some((item) => item.id === input.todoId)) throw new Error("关联 Todo 不存在");
    await validateTaskSources(task, input.sources, input.claim, options.author);
    const existing = options.id ? await db.agentTaskRecords.get(options.id) : undefined;
    if (options.id && (!existing || existing.taskId !== task.id)) throw new Error("记录不属于当前任务");
    if (existing && options.expectedRevision !== existing.revision) throw new Error("记录已更新，请重新读取后修改");
    if (!existing && options.expectedRevision !== undefined) throw new Error("新记录不应指定旧版本");
    if (!existing && options.runId) {
        const duplicate = (await listTaskRecords(task.id)).find((record) => record.runId === options.runId && record.author === options.author && record.kind === input.kind && record.claim === input.claim && record.title === input.title.trim() && record.body === input.body.trim() && record.todoId === input.todoId && JSON.stringify(record.sources) === JSON.stringify(input.sources));
        if (duplicate) return duplicate;
    }
    const at = nowIso();
    const record: AgentTaskRecord = {
        ...input,
        title: input.title.trim(),
        body: input.body.trim(),
        id: existing?.id ?? createId("trec"),
        taskId: task.id,
        revision: (existing?.revision ?? 0) + 1,
        author: options.author,
        runId: options.runId,
        createdAt: existing?.createdAt ?? at,
        updatedAt: at
    };
    await db.agentTaskRecords.put(record);
    await db.agentTaskRecordVersions.add({
        ...record,
        recordId: record.id,
        versionId: `${record.id}:${record.revision}`
    });
    await db.agentTasks.update(task.id, {updatedAt: at});
    return record;
}

export async function saveTaskRecord(taskId: string, input: TaskRecordInput, options: {
    id?: string;
    expectedRevision?: number
} = {}): Promise<AgentTaskRecord> {
    return db.transaction("rw", db.tables, async () => writeTaskRecord(await editableAgentTask(taskId), input, {
        ...options,
        author: "user"
    }));
}

/** Genuine generation evidence is owned by the task and reflects current local media/slot state. */
export async function taskGenerationSource(task: Pick<AgentTask, "id" | "threadId">, jobId: string) {
    const soundJob = await db.audioGenerationJobs.get(jobId);
    if (soundJob) return taskAudioGenerationSource(task, soundJob);
    const job = await db.agentGenerationJobs.get(jobId);
    const run = job && await db.agentRuns.get(job.runId);
    if (!job || !run || run.taskId !== task.id || job.threadId !== task.threadId || run.threadId !== task.threadId || !job.batchId) throw new Error("生成结果不属于当前任务批次");
    const batch = await db.agentGenerationBatches.get(job.batchId);
    if (!batch || batch.taskId !== task.id || batch.threadId !== task.threadId) throw new Error("生成批次来源已失效");
    const media = job.result && await db.media.get(job.result.mediaId);
    const available = !!media && media.projectId === job.projectId && !!media.blob.size && media.mimeType.startsWith(`${job.kind}/`) && ['downloaded', 'applied', 'conflict'].includes(job.status);
    let applied = false;
    try {
        applied = available && (await readGenerationTarget(job.target)).slot.result?.mediaId === media!.id;
    } catch { /* Downloaded output survives target deletion. */
    }
    return {
        id: job.id,
        batchId: job.batchId,
        status: job.status,
        result: job.result,
        label: `${job.kind === 'image' ? '图片' : '视频'} · ${job.model}`,
        available,
        applied,
        supportsResult: available,
        body: JSON.stringify({
            jobId: job.id,
            batchId: job.batchId,
            status: job.status,
            target: job.target,
            result: available ? job.result : undefined,
            available,
            applied,
            error: job.error
        })
    };
}

/** Shared source inventory; no remote refresh and no attribution to reading runs. */
export async function listTaskGenerationSources(task: AgentTask) {
    return db.transaction("r", db.tables, async () => {
        const sources: Awaited<ReturnType<typeof taskGenerationSource>>[] = [];
        const runs = await db.agentRuns.where("taskId").equals(task.id).toArray();
        const runIds = new Set(runs.filter(run => run.threadId === task.threadId).map(run => run.id));
        const jobs = await db.agentGenerationJobs.where("threadId").equals(task.threadId).toArray();
        for (const job of jobs.filter(job => job.batchId && runIds.has(job.runId))) {
            const batch = await db.agentGenerationBatches.get(job.batchId!);
            if (batch?.taskId === task.id && batch.threadId === task.threadId) sources.push(await Promise.resolve(taskGenerationSource(task, job.id)));
        }
        const soundJobs = await db.audioGenerationJobs.where("projectId").equals(task.projectId).toArray();
        for (const job of soundJobs) {
            if (await Promise.resolve(ownedTaskAudioGenerationJob(task, job))) sources.push(await Promise.resolve(taskAudioGenerationSource(task, job)));
        }
        return sources;
    });
}

import {collectReferenceEvidence, historicalToolSummary, toolReferenceAttachments} from "./referenceEvidence";
import {provesCompletedEffect} from "@/db/agentTaskRecords";
import {
  ownedTaskAudioGenerationJob,
  SOUND_GENERATION_TOOLS,
  taskAudioGenerationSource,
  taskAudioToolSource
} from "@/db/taskAudioGenerationEvidence";
import {db} from "@/db/database";
import type {AgentTask} from "@/domain/agent";
import type {WrapupEvidence, WrapupSnapshot} from "@/domain/agentTaskWrapup";
import {targetRevision} from "@/lib/productionRevision";
import {type BusinessKind, getRow, navigation, projection} from "./businessStore";
import {parseGenerationSlot} from "@/domain/slot";

const kinds = ["project", "episode", "beat", "shot", "character", "scene", "prop", "style", "media"];

function json(value: unknown): Record<string, unknown> {
    try {
        const parsed = typeof value === "string" ? JSON.parse(value) : value;
        return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    } catch {
        return {};
    }
}

/** Caller opens a consistent read transaction; full fingerprints include omitted history. */
export async function collectWrapupSnapshot(task: AgentTask, includeAllEvidence = false): Promise<WrapupSnapshot> {
    const runs = (await db.agentRuns.where("threadId").equals(task.threadId).toArray()).filter(r => r.taskId === task.id);
    const runIds = new Set(runs.map(r => r.id));
    const messages = (await db.chatMessages.where("threadId").equals(task.threadId).sortBy("createdAt")).filter(m => m.role === "user" || !!m.runId && runIds.has(m.runId));
    const calls = (await db.agentToolCalls.where("threadId").equals(task.threadId).toArray()).filter(c => runIds.has(c.runId));
    const records = await db.agentTaskRecords.where("taskId").equals(task.id).sortBy("updatedAt");
    const jobs = (await db.agentGenerationJobs.where("threadId").equals(task.threadId).toArray()).filter(j => runIds.has(j.runId));
    const batches = (await db.agentGenerationBatches.where("threadId").equals(task.threadId).toArray()).filter(batch => runIds.has(batch.runId));
    const batchItems = (await db.agentGenerationBatchItems.where("threadId").equals(task.threadId).toArray()).filter(item => batches.some(batch => batch.id === item.batchId));
    const evidence: WrapupEvidence[] = [], fingerprints: unknown[] = [];
    const add = (item: WrapupEvidence, raw: unknown) => {
        fingerprints.push([item.id, targetRevision(raw)]);
        evidence.push({...item, body: item.body.slice(0, 1800), truncated: item.body.length > 1800});
    };
    const entityIds = new Set<string>();
    // Cache hits and invalid locators can settle without any IndexedDB request.
    // Callers adopt this native promise through the transaction-zone Promise; a long
    // loop of bare awaits otherwise exhausts Dexie's zone tracking in real browsers.
    async function entity(kind: BusinessKind, id: string, ownerId?: string, episodeId?: string, label?: string) {
        const key = `entity:${kind}:${id}`;
        if (entityIds.has(key)) return;
        entityIds.add(key);
        try {
            const row = await getRow(kind, id, ownerId, episodeId);
            const link = navigation(kind, row);
            add({
                id: key,
                kind: "entity",
                label: link.label,
                body: JSON.stringify(projection(kind, row)),
                outcome: "fact",
                available: true,
                supportsResult: true,
                href: link.href
            }, row);
        } catch {
            add({
                id: key,
                kind: "entity",
                label: label ?? `${kind} · ${id}`,
                body: "原目标已删除或不再属于原范围",
                outcome: "unresolved",
                available: false
            }, null);
        }
    }

    for (const call of calls) {
        const value = json(call.result), args = json(call.arguments);
        const unsettled = !['completed', 'failed', 'rejected'].includes(call.status);
        const generation = ["submit_generation", "apply_generation", "check_generation"].includes(call.name);
        const failed = call.status !== "completed" || !!value.error || value.ok === false || value.success === false || (!generation && value.applied === false);
        const outcome: WrapupEvidence['outcome'] = unsettled || failed ? "unresolved" : generation ? (value.status === "applied" ? "applied" : value.status === "downloaded" ? "downloaded" : "unresolved") : "fact";
        add({
            id: `tool:${call.id}`,
            kind: "tool",
            label: call.title,
            body: JSON.stringify({
                status: call.status,
                result: historicalToolSummary(call.name, call.result, task.projectId ?? "") ?? value,
                error: call.error
            }),
            outcome,
            available: true,
            supportsResult: call.status === "completed" && provesCompletedEffect(call)
        }, call);
        if ((SOUND_GENERATION_TOOLS as readonly string[]).includes(call.name)) {
            const current = call.status === "completed" ? await Promise.resolve(taskAudioToolSource(task, call)) : undefined;
            const source = evidence.at(-1)!;
            source.supportsResult = current?.supportsResult === true;
            source.outcome = current?.supportsResult ? current.applied ? "applied" : "downloaded" : "unresolved";
            source.available = current?.available === true;
            source.body = current?.body.slice(0, 1800) ?? "当前声音成果不可核实；原工具返回只记录当时事实，不能证明文件仍可交付。";
            source.truncated = !!current && current.body.length > 1800;
            fingerprints.push([source.id, current?.body ?? null]);
        }
        const rows = Array.isArray(value.items) ? value.items : [value];
        for (const item of rows) {
            const row = json(item);
            const kind = typeof row.kind === 'string' && kinds.includes(row.kind) ? row.kind : typeof args.kind === 'string' && kinds.includes(args.kind) ? args.kind : call.name.split('_')[0];
            const id = typeof row.id === 'string' ? row.id : typeof args.id === 'string' ? args.id : undefined;
            if (id && kinds.includes(kind)) {
                await Promise.resolve(entity(kind as BusinessKind, id, typeof row.ownerId === 'string' ? row.ownerId : typeof args.ownerId === 'string' ? args.ownerId : undefined, typeof row.episodeId === 'string' ? row.episodeId : typeof args.episodeId === 'string' ? args.episodeId : undefined, typeof row.label === 'string' ? row.label : undefined));
                // Keep successful deletion as a historical effect. Creation/update/copy
                // evidence cannot certify a currently delivered object after its removal.
                if (call.effect === 'write' && !call.name.includes('_delete') && !evidence.find(e => e.id === `entity:${kind}:${id}`)?.available) {
                    const source = evidence.find(e => e.id === `tool:${call.id}`)!;
                    source.supportsResult = false;
                    source.outcome = 'unresolved';
                    source.body = `${source.body}\n当前关联目标不可用；此结果仅证明当时执行过操作，不能证明成果仍可交付。`;
                }
            }
        }
    }
    for (const batch of batches) {
        const items = batchItems.filter(item => item.batchId === batch.id);
        const unresolved = batch.status === 'draft' || items.some(item => item.state === 'queued') || jobs.some(job => job.batchId === batch.id && ['submitting', 'submitted', 'running', 'downloading', 'remote_completed', 'unknown'].includes(job.status));
        add({
            id: `batch:${batch.id}`,
            kind: 'generation',
            label: `批量生成 · ${batch.title}`,
            body: JSON.stringify({
                status: batch.status,
                candidates: items.map(item => ({
                    id: item.id,
                    state: item.state,
                    jobId: item.jobId,
                    selected: batch.selections[item.targetKey] === item.id
                })),
                pauseReason: batch.pauseReason
            }),
            outcome: unresolved ? 'unresolved' : 'fact',
            available: true,
            supportsResult: false
        }, {batch, items});
    }
    for (const job of jobs) {
        const target = job.target;
        await Promise.resolve(entity(target.kind, target.entityId, target.projectId, 'episodeId' in target ? target.episodeId : undefined));
        const media = job.result ? await db.media.get(job.result.mediaId) : undefined;
        let applied = false, href: string | undefined;
        try {
            const row = await getRow(target.kind, target.entityId, target.projectId, 'episodeId' in target ? target.episodeId : undefined);
            href = navigation(target.kind, row).href;
            const slot = target.kind === 'shot' ? row[target.slot ?? 'clip'] : json(row.slots)[target.slot];
            applied = !!media && parseGenerationSlot(slot).result?.mediaId === media.id;
        } catch {/* Missing targets remain historical evidence. */
        }
        const status = applied ? 'applied' : media && (['downloaded', 'applied', 'conflict'].includes(job.status)) ? 'downloaded' : 'unresolved';
        for (const call of calls.filter(call => call.id === job.callId || json(call.arguments).jobId === job.id)) {
            const source = evidence.find(item => item.id === `tool:${call.id}`);
            if (source) {
                source.supportsResult = status !== "unresolved";
                source.outcome = status;
                source.available = !!media;
                source.body = `${source.body}\n当前输出状态：${status}；原工具返回只记录当时事实。`;
            }
        }
        add({
            id: `generation:${job.id}`,
            kind: "generation",
            label: `${job.kind === 'image' ? '图片' : '视频'} · ${job.model}`,
            body: JSON.stringify({
                status: job.status,
                currentOutcome: status,
                target: job.target,
                result: job.result,
                mediaAvailable: !!media,
                appliedToCurrentTarget: applied,
                error: job.error
            }),
            outcome: status,
            available: !!media,
            supportsResult: status !== "unresolved",
            href
        }, {
            ...job,
            media: media ? {
                id: media.id,
                projectId: media.projectId,
                mimeType: media.mimeType,
                size: media.blob.size
            } : null,
            currentApplied: applied
        });
    }
    for (const job of await db.audioGenerationJobs.where("projectId").equals(task.projectId).toArray()) {
        if (!await Promise.resolve(ownedTaskAudioGenerationJob(task, job))) continue;
        const source = await Promise.resolve(taskAudioGenerationSource(task, job));
        add({
            id: `generation:${job.id}`, kind: "generation", label: source.label, body: source.body,
            outcome: source.supportsResult ? source.applied ? "applied" : "downloaded" : "unresolved",
            available: source.available, supportsResult: source.supportsResult,
            href: source.available ? `/p/${encodeURIComponent(job.projectId)}` : undefined
        }, {jobRevision: job.revision, source: source.body});
    }
    for (const record of records) add({
        id: `record:${record.id}`,
        kind: "record",
        label: record.title,
        body: JSON.stringify({
            kind: record.kind,
            claim: record.claim,
            author: record.author,
            body: record.body,
            sources: record.sources
        }),
        outcome: record.kind === 'question' ? 'unresolved' : 'fact',
        available: true
    }, record);
    for (const message of messages) add({
        id: `message:${message.id}`,
        kind: "message",
        label: message.role === 'user' ? '用户要求与反馈' : 'AI 回复（待核实）',
        body: message.content,
        outcome: message.role === 'assistant' && message.status !== 'complete' ? 'unresolved' : 'fact',
        available: true
    }, message);
    if (task.projectId) {
        const attachments = [
            ...messages.flatMap(message => message.attachments ?? []),
            ...calls.filter(call => call.status === "completed").flatMap(call => toolReferenceAttachments(call.result, task.projectId!)),
        ];
        for (const source of await collectReferenceEvidence(task.projectId, attachments)) add(source.evidence, source.fingerprint);
    }
    // Prioritize unresolved outcomes and the latest user corrections. Record all omissions.
    const ordered = [...evidence].reverse(), selected: WrapupEvidence[] = [];
    const take = (items: WrapupEvidence[], count: number) => {
        for (const item of items.filter(item => !selected.some(s => s.id === item.id)).slice(0, count)) selected.push(item);
    };
    take(ordered.filter(e => e.outcome === 'unresolved'), 6);
    for (const kind of ['generation', 'entity', 'tool', 'record', 'reference'] as const) take(ordered.filter(e => e.kind === kind), Math.min(8, 48 - selected.length));
    take(ordered.filter(e => e.kind === 'message'), Math.min(10, 48 - selected.length));
    take(ordered, 48 - selected.length);
    const selectedIds = new Set(selected.map(e => e.id));
    return {
        fingerprint: targetRevision({
            project: task.projectId ? await db.projects.get(task.projectId) : null,
            task: {
                id: task.id,
                projectId: task.projectId,
                title: task.title,
                goal: task.goal,
                plan: task.plan,
                acceptanceCriteria: task.acceptanceCriteria ?? [],
                revision: task.revision ?? 1,
                artifacts: task.artifacts
            },
            runs: runs.map(r => ({id: r.id, status: r.status, updatedAt: r.updatedAt})),
            sources: fingerprints.sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)))
        }),
        taskRevision: task.revision ?? 1,
        criteria: task.acceptanceCriteria ?? [],
        evidence: includeAllEvidence ? evidence.map(item => selectedIds.has(item.id) ? item : {
            ...item,
            body: "",
            truncated: true
        }) : selected,
        coverage: {
            total: evidence.length,
            included: selected.length,
            omitted: evidence.length - selected.length,
            truncated: selected.filter(e => e.truncated).length
        }
    };
}
